('monstera-deliciosa', 'Monstera deliciosa', 'Araceae', 'Monstera', 'مونستيرا', 'A tropical climbing aroid famous for large, glossy leaves that develop natural splits and holes as they mature.', 'نبتة استوائية متسلقة تشتهر بأوراقها الكبيرة اللامعة التي تظهر فيها شقوق وفتحات طبيعية كلما نضجت.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 16, 30, array['indoor']::text[], 'easy', 'large', 'climbing', false, false, false, false, array['Give it a moss pole so leaves grow larger.','Let the top 5 cm of soil dry before watering.']::text[], array['ثبّت لها عمود طحلب عشان تكبر أوراقها.','خل أول ٥ سم من التربة تجف قبل الري.']::text[], array['Yellow lower leaves from overwatering','Small leaves without splits from low light']::text[], array['اصفرار الأوراق السفلية بسبب زيادة الري','أوراق صغيرة بدون شقوق بسبب قلة الإضاءة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Monstera%20deliciosa','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Monstera%20deliciosa']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'monstera deliciosa', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Monstera_deliciosa2.jpg/960px-Monstera_deliciosa2.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Monstera_deliciosa2.jpg/500px-Monstera_deliciosa2.jpg","license":"CC BY-SA 3.0","attribution":null,"source_url":"https://commons.wikimedia.org/wiki/File:Monstera_deliciosa2.jpg"}'::jsonb, '2026-11-02', null),
('monstera-adansonii', 'Monstera adansonii', 'Araceae', 'Swiss Cheese Vine', 'مونستيرا أدانسوني', 'A vining Monstera with thin leaves full of oval windows, ideal for trailing from shelves or climbing a support.', 'مونستيرا متسلقة بأوراق رقيقة مليئة بفتحات بيضاوية، تناسب الرفوف أو التسلق على دعامة.', array['medium','bright_indirect']::text[], 'moderate', 'high', 16, 29, array['indoor']::text[], 'moderate', 'medium', 'trailing', false, false, false, false, array['Prefers higher humidity than its larger cousin.','Keep soil lightly moist, never soggy.']::text[], array['تحب رطوبة أعلى من المونستيرا الكبيرة.','خل التربة رطبة بشكل خفيف بدون تشبع.']::text[], array['Crispy brown edges in dry air','Root rot in heavy, wet soil']::text[], array['حواف بنية جافة في الهواء الجاف','تعفن الجذور في التربة الثقيلة المبللة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Monstera%20adansonii','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Monstera%20adansonii']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Monstera_adansonii_79319231.jpg/960px-Monstera_adansonii_79319231.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Monstera_adansonii_79319231.jpg/500px-Monstera_adansonii_79319231.jpg","license":"CC BY 4.0","attribution":"Aitor","source_url":"https://commons.wikimedia.org/wiki/File:Monstera_adansonii_79319231.jpg"}'::jsonb, '2026-11-02', null),
('epipremnum-aureum', 'Epipremnum aureum', 'Araceae', 'Golden Pothos', 'بوتس ذهبي', 'A forgiving trailing vine with heart-shaped, gold-marbled leaves that tolerates a wide range of indoor conditions.', 'نبتة متدلية متسامحة بأوراق قلبية مرقطة بالذهبي، تتحمل ظروفًا داخلية متنوعة.', array['low','medium','bright_indirect']::text[], 'moderate', 'moderate', 15, 30, array['indoor']::text[], 'easy', 'medium', 'trailing', false, false, false, false, array['Water when the top half of the soil is dry.','Trim long vines to keep it full.']::text[], array['اسقها لما يجف نصف التربة العلوي.','قص الفروع الطويلة عشان تصير كثيفة.']::text[], array['Loss of variegation in low light','Yellow leaves from soggy soil']::text[], array['فقدان التلوين الذهبي في الإضاءة الضعيفة','اصفرار الأوراق بسبب التربة المشبعة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Epipremnum%20aureum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Epipremnum%20aureum']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'epipremnum aureum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Money_Plant_%28Epipremnum_aureum%29_4.jpg/960px-Money_Plant_%28Epipremnum_aureum%29_4.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Money_Plant_%28Epipremnum_aureum%29_4.jpg/500px-Money_Plant_%28Epipremnum_aureum%29_4.jpg","license":"CC BY-SA 3.0","attribution":"Mokkie","source_url":"https://commons.wikimedia.org/wiki/File:Money_Plant_(Epipremnum_aureum)_4.jpg"}'::jsonb, '2026-11-02', null),
('dracaena-trifasciata', 'Dracaena trifasciata', 'Asparagaceae', 'Snake Plant', 'نبتة الثعبان (سانسفيريا)', 'Upright, sword-like leaves that store water, making it one of the most drought- and neglect-tolerant houseplants.', 'أوراق قائمة تشبه السيوف وتخزن الماء، من أكثر النباتات الداخلية تحملًا للعطش والإهمال.', array['low','medium','bright_indirect']::text[], 'low', 'low', 13, 32, array['indoor']::text[], 'easy', 'medium', 'upright', false, false, false, true, array['Water every 2–4 weeks; less in winter.','Use a fast-draining cactus mix.']::text[], array['اسقها كل ٢–٤ أسابيع، وأقل في الشتاء.','استخدم تربة صبار سريعة التصريف.']::text[], array['Mushy leaf bases from overwatering','Leaves falling over in very low light']::text[], array['طراوة قاعدة الأوراق بسبب زيادة الري','ميلان الأوراق في الإضاءة الضعيفة جدًا']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Dracaena%20trifasciata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Dracaena%20trifasciata']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'sansevieria trifasciata', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Dracaena_trifasciata_50695143.jpg/960px-Dracaena_trifasciata_50695143.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Dracaena_trifasciata_50695143.jpg/500px-Dracaena_trifasciata_50695143.jpg","license":"CC BY 4.0","attribution":"Ian Webb","source_url":"https://commons.wikimedia.org/wiki/File:Dracaena_trifasciata_50695143.jpg"}'::jsonb, '2026-11-02', null),
('zamioculcas-zamiifolia', 'Zamioculcas zamiifolia', 'Araceae', 'ZZ Plant', 'زاميا (زد زد)', 'Glossy, waxy leaflets grow from underground rhizomes that store water, letting it cope with low light and missed waterings.', 'وريقات لامعة شمعية تنمو من جذامير تحت التربة تخزن الماء، فتتحمل الإضاءة الضعيفة ونسيان الري.', array['low','medium','bright_indirect']::text[], 'low', 'low', 15, 30, array['indoor']::text[], 'easy', 'medium', 'upright', false, false, false, false, array['Let the soil dry out completely between waterings.','Wipe leaves to keep their shine.']::text[], array['خل التربة تجف تمامًا بين كل ريّة.','امسح الأوراق عشان تحافظ على لمعتها.']::text[], array['Yellowing stems from overwatering','Slow growth in deep shade']::text[], array['اصفرار السيقان بسبب زيادة الري','نمو بطيء في الظل الشديد']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Zamioculcas%20zamiifolia','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Zamioculcas%20zamiifolia']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Zamioculcas_zamiifolia_1.jpg/960px-Zamioculcas_zamiifolia_1.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Zamioculcas_zamiifolia_1.jpg/500px-Zamioculcas_zamiifolia_1.jpg","license":"CC BY-SA 3.0","attribution":"User:WeFt","source_url":"https://commons.wikimedia.org/wiki/File:Zamioculcas_zamiifolia_1.jpg"}'::jsonb, '2026-11-02', null),
('chlorophytum-comosum', 'Chlorophytum comosum', 'Asparagaceae', 'Spider Plant', 'نبتة العنكبوت', 'Arching striped leaves and dangling baby plantlets make it a cheerful, easy plant for shelves and hanging baskets.', 'أوراق مقوسة مخططة ونبتات صغيرة متدلية تجعلها نبتة مبهجة وسهلة للرفوف والسلال المعلقة.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 10, 30, array['indoor']::text[], 'easy', 'small', 'trailing', false, false, false, false, array['Root the plantlets in water to make new plants.','Brown tips often come from hard tap water.']::text[], array['جذّر النبتات الصغيرة في الماء عشان تزرع نباتات جديدة.','الأطراف البنية غالبًا من ماء الحنفية العسر.']::text[], array['Brown leaf tips from fluoride or salts','Pale leaves in too much direct sun']::text[], array['أطراف بنية بسبب الأملاح في الماء','شحوب الأوراق في الشمس المباشرة القوية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Chlorophytum%20comosum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Chlorophytum%20comosum']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'chlorophytum comosum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Chlorophytum_comosum_in_China.jpg/960px-Chlorophytum_comosum_in_China.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Chlorophytum_comosum_in_China.jpg/500px-Chlorophytum_comosum_in_China.jpg","license":"CC BY-SA 4.0","attribution":"Dinkun Chen","source_url":"https://commons.wikimedia.org/wiki/File:Chlorophytum_comosum_in_China.jpg"}'::jsonb, '2026-11-02', null),
('spathiphyllum-wallisii', 'Spathiphyllum wallisii', 'Araceae', 'Peace Lily', 'زنبق السلام', 'Dark green leaves and elegant white spathes; it droops visibly when thirsty and recovers quickly after watering.', 'أوراق خضراء داكنة وأغلفة زهرية بيضاء أنيقة، تذبل بوضوح لما تعطش وتنتعش بسرعة بعد الري.', array['low','medium','bright_indirect']::text[], 'high', 'high', 16, 30, array['indoor']::text[], 'easy', 'medium', 'bushy', false, true, false, false, array['Keep soil evenly moist but not waterlogged.','Brighter indirect light encourages flowering.']::text[], array['خل التربة رطبة باستمرار بدون تشبع.','الإضاءة غير المباشرة الأقوى تشجع التزهير.']::text[], array['Dramatic wilting when dry','No flowers in deep shade']::text[], array['ذبول واضح عند العطش','عدم التزهير في الظل الشديد']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Spathiphyllum%20wallisii','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Spathiphyllum%20wallisii']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'spathiphyllum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Peace_lily_-_1_-_cropped.jpg/960px-Peace_lily_-_1_-_cropped.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Peace_lily_-_1_-_cropped.jpg/500px-Peace_lily_-_1_-_cropped.jpg","license":"CC BY-SA 4.0","attribution":"W.carter","source_url":"https://commons.wikimedia.org/wiki/File:Peace_lily_-_1_-_cropped.jpg"}'::jsonb, '2026-11-02', null),
('ficus-elastica', 'Ficus elastica', 'Moraceae', 'Rubber Plant', 'فيكس مطاطي', 'Thick, glossy, deep-green leaves on an upright trunk; grows into a statement tree with bright light.', 'أوراق سميكة لامعة خضراء داكنة على جذع قائم، تكبر لتصير شجرة لافتة في الإضاءة الجيدة.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 15, 30, array['indoor']::text[], 'easy', 'large', 'tree', false, false, false, false, array['Rotate monthly for even growth.','Dust leaves so they can photosynthesise well.']::text[], array['لفّها كل شهر عشان تنمو بشكل متوازن.','نظف الأوراق من الغبار عشان تقدر تبني غذاءها.']::text[], array['Leaf drop after sudden moves or cold drafts','Leggy growth in low light']::text[], array['تساقط الأوراق بعد النقل المفاجئ أو تيارات الهواء البارد','نمو طويل ضعيف في الإضاءة الضعيفة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Ficus%20elastica','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Ficus%20elastica']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'ficus', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Ficus_elastica_leaves_02.JPG/960px-Ficus_elastica_leaves_02.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Ficus_elastica_leaves_02.JPG/500px-Ficus_elastica_leaves_02.JPG","license":"CC BY-SA 3.0","attribution":"B.navez","source_url":"https://commons.wikimedia.org/wiki/File:Ficus_elastica_leaves_02.JPG"}'::jsonb, '2026-11-02', null),
('ficus-lyrata', 'Ficus lyrata', 'Moraceae', 'Fiddle-Leaf Fig', 'فيكس ليراتا', 'Large violin-shaped leaves on a tree form; dramatic but particular about consistent light and watering.', 'أوراق كبيرة على شكل كمان على هيئة شجرة؛ مبهرة لكنها حساسة وتحتاج ثبات في الإضاءة والري.', array['bright_indirect']::text[], 'moderate', 'moderate', 16, 30, array['indoor']::text[], 'hard', 'large', 'tree', false, false, false, false, array['Place close to a bright window and avoid moving it.','Water thoroughly once the top 5 cm dries.']::text[], array['حطها قريب من شباك مضيء وتجنب تحريكها.','اسقها جيدًا لما تجف أول ٥ سم.']::text[], array['Brown spots from root rot or irregular watering','Leaf drop after relocation']::text[], array['بقع بنية بسبب تعفن الجذور أو الري غير المنتظم','تساقط الأوراق بعد نقلها']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Ficus%20lyrata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Ficus%20lyrata']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'ficus', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Starr_031108-0130_Ficus_lyrata.jpg/960px-Starr_031108-0130_Ficus_lyrata.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Starr_031108-0130_Ficus_lyrata.jpg/500px-Starr_031108-0130_Ficus_lyrata.jpg","license":"CC BY 3.0","attribution":"Forest &amp; Kim Starr","source_url":"https://commons.wikimedia.org/wiki/File:Starr_031108-0130_Ficus_lyrata.jpg"}'::jsonb, '2026-11-02', null),
('chamaedorea-elegans', 'Chamaedorea elegans', 'Arecaceae', 'Parlour Palm', 'نخلة الصالون', 'A compact, slow-growing palm with soft feathery fronds that copes well with indoor shade.', 'نخلة صغيرة بطيئة النمو بسعف ريشي ناعم، تتأقلم جيدًا مع الظل داخل البيت.', array['low','medium']::text[], 'moderate', 'moderate', 16, 29, array['indoor']::text[], 'easy', 'medium', 'upright', false, false, false, false, array['Keep away from hot direct sun, which scorches fronds.','Water when the top 3 cm feels dry.']::text[], array['أبعدها عن الشمس المباشرة الحارة لأنها تحرق السعف.','اسقها لما تجف أول ٣ سم.']::text[], array['Brown frond tips in dry air','Spider mites in hot, dry rooms']::text[], array['أطراف سعف بنية في الهواء الجاف','العنكبوت الأحمر في الغرف الحارة الجافة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Chamaedorea%20elegans','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Chamaedorea%20elegans']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'chamaedorea elegans', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Chamaedorea_elegans_Mart.JPG/960px-Chamaedorea_elegans_Mart.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Chamaedorea_elegans_Mart.JPG/500px-Chamaedorea_elegans_Mart.JPG","license":"CC BY-SA 3.0","attribution":"Bachelot Pierre J-P","source_url":"https://commons.wikimedia.org/wiki/File:Chamaedorea_elegans_Mart.JPG"}'::jsonb, '2026-11-02', null),
('peperomia-obtusifolia', 'Peperomia obtusifolia', 'Piperaceae', 'Baby Rubber Plant', 'بيبروميا', 'Thick, rounded, semi-succulent leaves on a compact plant that is happy on desks and shelves.', 'أوراق دائرية سميكة شبه عصارية على نبتة صغيرة ترتاح على المكاتب والرفوف.', array['medium','bright_indirect']::text[], 'low', 'moderate', 16, 29, array['indoor']::text[], 'easy', 'small', 'bushy', false, false, false, false, array['Let soil dry halfway before watering.','A small pot with good drainage suits it best.']::text[], array['خل التربة تجف للنصف قبل الري.','أصيص صغير بتصريف جيد يناسبها أكثر.']::text[], array['Soft stems from overwatering','Leaf drop from cold']::text[], array['سيقان طرية بسبب زيادة الري','تساقط الأوراق من البرد']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Peperomia%20obtusifolia','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Peperomia%20obtusifolia']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'peperomia obtusifolia', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Peperomia_obtusifolia_3-OB9.jpg/960px-Peperomia_obtusifolia_3-OB9.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Peperomia_obtusifolia_3-OB9.jpg/500px-Peperomia_obtusifolia_3-OB9.jpg","license":"CC BY-SA 4.0","attribution":"Jerzy Opioła","source_url":"https://commons.wikimedia.org/wiki/File:Peperomia_obtusifolia_3-OB9.jpg"}'::jsonb, '2026-11-02', null),
('pilea-peperomioides', 'Pilea peperomioides', 'Urticaceae', 'Chinese Money Plant', 'بيليا (نبتة النقود الصينية)', 'Round, coin-like leaves on long stalks; produces offsets that are easy to share.', 'أوراق دائرية تشبه العملات على أعناق طويلة، وتنتج فسائل سهلة المشاركة.', array['bright_indirect']::text[], 'moderate', 'moderate', 13, 29, array['indoor']::text[], 'easy', 'small', 'upright', false, false, false, false, array['Rotate weekly; it leans strongly toward light.','Water when the top half of the soil is dry.']::text[], array['لفّها كل أسبوع لأنها تميل بقوة جهة الضوء.','اسقها لما يجف نصف التربة العلوي.']::text[], array['Curling leaves from too much direct sun','Drooping from overwatering']::text[], array['تجعد الأوراق من الشمس المباشرة الزائدة','تدلي الأوراق من زيادة الري']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Pilea%20peperomioides','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Pilea%20peperomioides']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Pilea_peperomioides_Chinese_money_plant.jpg/960px-Pilea_peperomioides_Chinese_money_plant.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Pilea_peperomioides_Chinese_money_plant.jpg/500px-Pilea_peperomioides_Chinese_money_plant.jpg","license":"CC0","attribution":"Husky","source_url":"https://commons.wikimedia.org/wiki/File:Pilea_peperomioides_Chinese_money_plant.jpg"}'::jsonb, '2026-11-02', null),
('maranta-leuconeura', 'Maranta leuconeura', 'Marantaceae', 'Prayer Plant', 'نبتة الصلاة (مارانتا)', 'Patterned leaves that fold upward at night, which is how it earned the name prayer plant.', 'أوراق منقوشة تنطوي للأعلى في الليل، ومن هنا جاء اسمها نبتة الصلاة.', array['low','medium']::text[], 'high', 'high', 16, 29, array['indoor']::text[], 'moderate', 'small', 'bushy', false, false, false, false, array['Use filtered or rested water to avoid brown tips.','Group with other plants to raise humidity.']::text[], array['استخدم ماء مفلتر أو ماء مترك يوم عشان تتجنب الأطراف البنية.','جمّعها مع نباتات ثانية عشان ترفع الرطوبة.']::text[], array['Crispy edges in dry air','Faded pattern in direct sun']::text[], array['حواف جافة في الهواء الجاف','بهتان النقوش في الشمس المباشرة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Maranta%20leuconeura','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Maranta%20leuconeura']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Maranta_leuconeura3.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Maranta_leuconeura3.jpg","license":"CC BY-SA 3.0","attribution":"Kurt Stüber [1]","source_url":"https://commons.wikimedia.org/wiki/File:Maranta_leuconeura3.jpg"}'::jsonb, '2026-11-02', null),
('goeppertia-orbifolia', 'Goeppertia orbifolia', 'Marantaceae', 'Calathea Orbifolia', 'كالاثيا أوربيفوليا', 'Broad round leaves with silver-green stripes; a showpiece for humid, shaded rooms.', 'أوراق دائرية عريضة بخطوط فضية خضراء، قطعة مميزة للغرف الرطبة المظللة.', array['medium']::text[], 'high', 'high', 18, 28, array['indoor']::text[], 'hard', 'medium', 'bushy', false, false, false, false, array['Needs high humidity; a humidifier helps in Saudi homes with AC.','Keep soil consistently moist.']::text[], array['تحتاج رطوبة عالية؛ جهاز ترطيب يساعد في البيوت المكيفة.','خل التربة رطبة باستمرار.']::text[], array['Curling, crispy leaves in dry air','Spider mites']::text[], array['التفاف وجفاف الأوراق في الهواء الجاف','العنكبوت الأحمر']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Goeppertia%20orbifolia','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Goeppertia%20orbifolia']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'calathea', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Houseplant_Calathea_orbifolia.jpg/960px-Houseplant_Calathea_orbifolia.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Houseplant_Calathea_orbifolia.jpg/500px-Houseplant_Calathea_orbifolia.jpg","license":"CC BY-SA 4.0","attribution":"Supsoph","source_url":"https://commons.wikimedia.org/wiki/File:Houseplant_Calathea_orbifolia.jpg"}'::jsonb, '2026-11-02', null),
('aloe-vera', 'Aloe vera', 'Asphodelaceae', 'Aloe Vera', 'صبار الألوفيرا', 'A sun-loving succulent with thick, gel-filled leaves; very tolerant of heat and dry air.', 'عصارية تحب الشمس بأوراق سميكة مليئة بالجل، تتحمل الحرارة والهواء الجاف بشكل كبير.', array['bright_indirect','full_sun']::text[], 'low', 'low', 10, 40, array['indoor','outdoor']::text[], 'easy', 'small', 'rosette', true, false, false, true, array['Water deeply, then wait until the soil is fully dry.','Acclimatise gradually before full summer sun.']::text[], array['اسقها ريّة عميقة وانتظر لين تجف التربة تمامًا.','عوّدها تدريجيًا قبل شمس الصيف الكاملة.']::text[], array['Soft, brown leaves from overwatering','Thin, pale leaves in low light']::text[], array['أوراق طرية بنية بسبب زيادة الري','أوراق رفيعة شاحبة في الإضاءة الضعيفة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Aloe%20vera','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Aloe%20vera']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'aloe vera', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Aloe_vera_flower_inset.png/960px-Aloe_vera_flower_inset.png","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Aloe_vera_flower_inset.png/500px-Aloe_vera_flower_inset.png","license":"CC BY-SA 3.0","attribution":"Collage by en:User:MidgleyDJ, original images from Wikimedia commons (Image:Aloe_vera_offsets.jpg and Image:Aloe_vera_C.jpg)","source_url":"https://commons.wikimedia.org/wiki/File:Aloe_vera_flower_inset.png"}'::jsonb, '2026-11-02', null),
('haworthiopsis-attenuata', 'Haworthiopsis attenuata', 'Asphodelaceae', 'Zebra Haworthia', 'هاورثيا الزيبرا', 'A small rosette succulent with white-striped leaves; tolerates less light than most succulents.', 'عصارية صغيرة على شكل وردة بأوراق مخططة بالأبيض، تتحمل إضاءة أقل من أغلب العصاريات.', array['medium','bright_indirect']::text[], 'low', 'low', 10, 35, array['indoor']::text[], 'easy', 'small', 'rosette', false, false, false, true, array['Water only when the soil is completely dry.','Ideal for a bright desk or windowsill.']::text[], array['اسقها بس لما تجف التربة تمامًا.','مثالية لمكتب مضيء أو حافة شباك.']::text[], array['Rot from water sitting in the rosette','Reddish leaves from harsh sun stress']::text[], array['تعفن من بقاء الماء داخل الوردة','احمرار الأوراق من إجهاد الشمس القوية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Haworthiopsis%20attenuata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Haworthiopsis%20attenuata']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'haworthia fasciata', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg/960px-Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg/500px-Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg","license":"CC BY 2.0","attribution":"stephen boisvert from Chicago, United States","source_url":"https://commons.wikimedia.org/wiki/File:Winterbourne_-_Haworthia_attenuata_(6120983526).jpg"}'::jsonb, '2026-11-02', null),
('echeveria-elegans', 'Echeveria elegans', 'Crassulaceae', 'Mexican Snowball', 'إيشيفيريا', 'A pale blue-green rosette succulent that stays compact and colourful in bright light.', 'عصارية وردية بلون أزرق مخضر فاتح، تبقى صغيرة وملونة في الإضاءة القوية.', array['bright_indirect','full_sun']::text[], 'low', 'low', 7, 35, array['indoor','outdoor']::text[], 'easy', 'small', 'rosette', false, false, false, true, array['Needs several hours of bright light daily.','Give afternoon shade in peak Saudi summer.']::text[], array['تحتاج عدة ساعات من الإضاءة القوية يوميًا.','وفّر لها ظل العصر في ذروة صيف السعودية.']::text[], array['Stretching (etiolation) in low light','Rot from overwatering']::text[], array['استطالة الساق في الإضاءة الضعيفة','التعفن من زيادة الري']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Echeveria%20elegans','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Echeveria%20elegans']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'echeveria elegans', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Echeveria_elegans_-_1.png/960px-Echeveria_elegans_-_1.png","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Echeveria_elegans_-_1.png/500px-Echeveria_elegans_-_1.png","license":"CC BY-SA 4.0","attribution":"EriaWei","source_url":"https://commons.wikimedia.org/wiki/File:Echeveria_elegans_-_1.png"}'::jsonb, '2026-11-02', null),
('crassula-ovata', 'Crassula ovata', 'Crassulaceae', 'Jade Plant', 'نبتة اليشم (كراسولا)', 'A long-lived succulent shrub with thick oval leaves and woody stems that can be shaped like a bonsai.', 'شجيرة عصارية معمّرة بأوراق بيضاوية سميكة وسيقان خشبية يمكن تشكيلها مثل البونساي.', array['bright_indirect','full_sun']::text[], 'low', 'low', 10, 35, array['indoor','outdoor']::text[], 'easy', 'medium', 'bushy', false, false, false, true, array['Water when the soil is dry; less in winter.','Use a heavy pot; it can become top-heavy.']::text[], array['اسقها لما تجف التربة، وأقل في الشتاء.','استخدم أصيص ثقيل لأنها ممكن تصير ثقيلة من فوق.']::text[], array['Shrivelled leaves when very dry','Leaf drop from overwatering']::text[], array['تجعد الأوراق عند العطش الشديد','تساقط الأوراق من زيادة الري']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Crassula%20ovata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Crassula%20ovata']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'crassula argentea', '2026-11-02', '{"url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Crassula_ovata_700.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Crassula_ovata_700.jpg","license":"CC BY-SA 3.0","attribution":"author is sannse.","source_url":"https://commons.wikimedia.org/wiki/File:Crassula_ovata_700.jpg"}'::jsonb, '2026-11-02', null),
('beaucarnea-recurvata', 'Beaucarnea recurvata', 'Asparagaceae', 'Ponytail Palm', 'نخلة ذيل الحصان', 'Not a true palm: a swollen trunk stores water beneath a fountain of long, curly leaves. Very heat tolerant.', 'ليست نخلة حقيقية: جذع منتفخ يخزن الماء تحت نافورة من الأوراق الطويلة المتموجة. تتحمل الحرارة بشكل كبير.', array['bright_indirect','full_sun']::text[], 'low', 'low', 10, 40, array['indoor','outdoor']::text[], 'easy', 'medium', 'tree', true, false, false, false, array['Water every 2–3 weeks; the trunk is its reservoir.','Thrives in bright Saudi light near windows.']::text[], array['اسقها كل ٢–٣ أسابيع؛ الجذع هو خزانها.','تزدهر في إضاءة السعودية القوية قرب الشبابيك.']::text[], array['Soft trunk from overwatering','Brown tips in dry indoor air (cosmetic)']::text[], array['طراوة الجذع من زيادة الري','أطراف بنية في الهواء الداخلي الجاف (شكلية)']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Beaucarnea%20recurvata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Beaucarnea%20recurvata']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'beaucarnea recurvata', '2026-11-02', '{"url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Beaucarnea_recurvata%2C_Ocampo%2C_Tamaulipas%2C_Mexico_1.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Beaucarnea_recurvata%2C_Ocampo%2C_Tamaulipas%2C_Mexico_1.jpg","license":"CC BY-SA 4.0","attribution":"juancruzado","source_url":"https://commons.wikimedia.org/wiki/File:Beaucarnea_recurvata,_Ocampo,_Tamaulipas,_Mexico_1.jpg"}'::jsonb, '2026-11-02', null),
('bougainvillea-glabra', 'Bougainvillea glabra', 'Nyctaginaceae', 'Bougainvillea', 'جهنمية', 'A vigorous flowering climber with vivid papery bracts; a classic of sunny Saudi walls and balconies.', 'متسلقة مزهرة قوية بأوراق زهرية ورقية زاهية؛ من كلاسيكيات الجدران والبلكونات المشمسة في السعودية.', array['full_sun']::text[], 'low', 'low', 5, 45, array['outdoor']::text[], 'easy', 'large', 'climbing', true, true, false, false, array['Flowers best when slightly dry between waterings.','Wear gloves: stems have thorns.']::text[], array['تزهر أفضل لما تجف قليلًا بين الريّات.','البس قفازات لأن السيقان فيها أشواك.']::text[], array['Few flowers from overwatering or too much nitrogen','Leaf drop after transplanting']::text[], array['قلة الأزهار من زيادة الري أو كثرة النيتروجين','تساقط الأوراق بعد الشتل']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Bougainvillea%20glabra','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Bougainvillea%20glabra']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Bougainvillea_glabra%2C_AA_Quesada_%28Costa_Rica%29_2009.jpg/960px-Bougainvillea_glabra%2C_AA_Quesada_%28Costa_Rica%29_2009.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Bougainvillea_glabra%2C_AA_Quesada_%28Costa_Rica%29_2009.jpg/500px-Bougainvillea_glabra%2C_AA_Quesada_%28Costa_Rica%29_2009.jpg","license":"CC BY 4.0","attribution":"Green Mostaza","source_url":"https://commons.wikimedia.org/wiki/File:Bougainvillea_glabra,_AA_Quesada_(Costa_Rica)_2009.jpg"}'::jsonb, '2026-11-02', null),
('salvia-rosmarinus', 'Salvia rosmarinus', 'Lamiaceae', 'Rosemary', 'إكليل الجبل', 'A fragrant woody herb with needle-like leaves, loved in the kitchen and suited to sunny, dry spots.', 'عشبة خشبية عطرية بأوراق إبرية، محبوبة في المطبخ وتناسب الأماكن المشمسة الجافة.', array['full_sun']::text[], 'low', 'low', 5, 38, array['outdoor']::text[], 'easy', 'small', 'bushy', true, false, true, false, array['Needs excellent drainage; avoid wet roots.','Harvest sprigs regularly to keep it bushy.']::text[], array['تحتاج تصريف ممتاز؛ تجنب بقاء الجذور مبللة.','اقطف الأغصان بانتظام عشان تبقى كثيفة.']::text[], array['Powdery mildew in still, humid air','Root rot in heavy soil']::text[], array['البياض الدقيقي في الهواء الرطب الراكد','تعفن الجذور في التربة الثقيلة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Salvia%20rosmarinus','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Salvia%20rosmarinus']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'rosmarinus officinalis', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Rosemary_in_bloom.JPG/960px-Rosemary_in_bloom.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Rosemary_in_bloom.JPG/500px-Rosemary_in_bloom.JPG","license":"CC BY-SA 4.0","attribution":"Margalob","source_url":"https://commons.wikimedia.org/wiki/File:Rosemary_in_bloom.JPG"}'::jsonb, '2026-11-02', null),
('ocimum-basilicum', 'Ocimum basilicum', 'Lamiaceae', 'Sweet Basil', 'ريحان', 'A fast-growing aromatic herb that loves warmth and sun; pinch tips often for bushier growth.', 'عشبة عطرية سريعة النمو تحب الدفء والشمس؛ اقرص الأطراف باستمرار عشان تصير أكثف.', array['bright_indirect','full_sun']::text[], 'high', 'moderate', 15, 35, array['indoor','outdoor']::text[], 'easy', 'small', 'bushy', false, false, true, false, array['Pinch off flower buds to keep leaves tender.','Water when the surface is dry; don''t let it wilt.']::text[], array['شيل البراعم الزهرية عشان تبقى الأوراق طرية.','اسقها لما يجف السطح ولا تخليها تذبل.']::text[], array['Wilting in hot afternoon sun','Aphids on new growth']::text[], array['الذبول في شمس العصر الحارة','حشرة المن على النمو الجديد']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Ocimum%20basilicum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Ocimum%20basilicum']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'ocimum basilicum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Ocimum_basilicum_8zz.jpg/960px-Ocimum_basilicum_8zz.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Ocimum_basilicum_8zz.jpg/500px-Ocimum_basilicum_8zz.jpg","license":"CC BY-SA 4.0","attribution":"Photo by David J. Stang","source_url":"https://commons.wikimedia.org/wiki/File:Ocimum_basilicum_8zz.jpg"}'::jsonb, '2026-11-02', null),
('mentha-spicata', 'Mentha spicata', 'Lamiaceae', 'Spearmint', 'نعناع', 'The classic mint of Saudi tea: vigorous, aromatic and happiest in its own pot with steady moisture.', 'النعناع الكلاسيكي للشاي السعودي: قوي وعطري ويرتاح أكثر في أصيص خاص مع رطوبة ثابتة.', array['bright_indirect','full_sun']::text[], 'high', 'moderate', 10, 35, array['indoor','outdoor']::text[], 'easy', 'small', 'bushy', false, false, true, false, array['Grow alone in a pot; roots spread aggressively.','Afternoon shade helps in the Saudi summer.']::text[], array['ازرعه في أصيص لحاله لأن جذوره تنتشر بقوة.','ظل العصر يساعده في صيف السعودية.']::text[], array['Wilting from heat and dry soil','Rust or mildew in crowded pots']::text[], array['الذبول من الحرارة وجفاف التربة','الصدأ أو البياض في الأصص المزدحمة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Mentha%20spicata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Mentha%20spicata']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'mentha', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Minze.jpg/960px-Minze.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Minze.jpg/500px-Minze.jpg","license":"CC BY-SA 3.0","attribution":"Simon Eugster --Simon 13:07, 2 July 2006 (UTC)","source_url":"https://commons.wikimedia.org/wiki/File:Minze.jpg"}'::jsonb, '2026-11-02', null),
('aglaonema-commutatum', 'Aglaonema commutatum', 'Araceae', 'Chinese Evergreen', 'أجلونيما', 'Patterned silver-green leaves on a tidy plant that tolerates low light and air conditioning well.', 'أوراق منقوشة بالفضي والأخضر على نبتة مرتبة تتحمل الإضاءة الضعيفة والمكيفات بشكل جيد.', array['low','medium']::text[], 'moderate', 'moderate', 16, 30, array['indoor']::text[], 'easy', 'medium', 'bushy', false, false, false, false, array['Water when the top 3–5 cm is dry.','Avoid cold AC drafts blowing directly on it.']::text[], array['اسقها لما تجف أول ٣–٥ سم.','تجنب هواء المكيف البارد المباشر عليها.']::text[], array['Yellow leaves from cold or overwatering','Mealybugs in leaf joints']::text[], array['اصفرار الأوراق من البرد أو زيادة الري','البق الدقيقي بين مفاصل الأوراق']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Aglaonema%20commutatum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Aglaonema%20commutatum']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'aglaonema modestum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/20260317_Aglaonema_commutatum.jpg/960px-20260317_Aglaonema_commutatum.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/20260317_Aglaonema_commutatum.jpg/500px-20260317_Aglaonema_commutatum.jpg","license":"CC BY 4.0","attribution":"Flocci Nivis","source_url":"https://commons.wikimedia.org/wiki/File:20260317_Aglaonema_commutatum.jpg"}'::jsonb, '2026-11-02', null),
('philodendron-hederaceum', 'Philodendron hederaceum', 'Araceae', 'Heartleaf Philodendron', 'فيلوديندرون قلبي', 'A fast, easy vine with soft heart-shaped leaves for hanging baskets or climbing poles.', 'متسلقة سريعة وسهلة بأوراق قلبية ناعمة للسلال المعلقة أو التسلق على الأعمدة.', array['low','medium','bright_indirect']::text[], 'moderate', 'moderate', 15, 30, array['indoor']::text[], 'easy', 'medium', 'trailing', false, false, false, false, array['Water when the top half of soil dries.','Pinch back to encourage fuller growth.']::text[], array['اسقها لما يجف نصف التربة العلوي.','قص الأطراف عشان تتشجع على نمو أكثف.']::text[], array['Leggy vines with small leaves in low light','Yellow leaves from overwatering']::text[], array['فروع طويلة بأوراق صغيرة في الإضاءة الضعيفة','اصفرار الأوراق من زيادة الري']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Philodendron%20hederaceum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Philodendron%20hederaceum']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'philodendron hederaceum', '2026-11-02', '{"url":"https://upload.wikimedia.org/wikipedia/commons/b/bb/Philodendron_scandens_subsp_oxycardium2.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/b/bb/Philodendron_scandens_subsp_oxycardium2.jpg","license":"CC BY-SA 3.0","attribution":"KENPEI","source_url":"https://commons.wikimedia.org/wiki/File:Philodendron_scandens_subsp_oxycardium2.jpg"}'::jsonb, '2026-11-02', null),
('dypsis-lutescens', 'Dypsis lutescens', 'Arecaceae', 'Areca Palm', 'نخلة الأريكا', 'Clustered golden stems and arching fronds create a soft tropical screen in bright rooms.', 'سيقان ذهبية متجمعة وسعف مقوس تصنع حاجز استوائي ناعم في الغرف المضيئة.', array['bright_indirect']::text[], 'moderate', 'moderate', 16, 32, array['indoor','outdoor']::text[], 'moderate', 'large', 'upright', false, false, false, false, array['Bright, filtered light; harsh sun yellows fronds.','Keep soil lightly moist in summer.']::text[], array['إضاءة قوية مفلترة؛ الشمس الحارقة تصفّر السعف.','خل التربة رطبة بشكل خفيف في الصيف.']::text[], array['Brown tips from dry air or salts','Spider mites']::text[], array['أطراف بنية من الهواء الجاف أو الأملاح','العنكبوت الأحمر']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Dypsis%20lutescens','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Dypsis%20lutescens']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'dypsis lutescens', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/%E6%95%A3%E5%B0%BE%E8%91%B5Dypsis_lutescens_20210511145013_05.jpg/960px-%E6%95%A3%E5%B0%BE%E8%91%B5Dypsis_lutescens_20210511145013_05.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/%E6%95%A3%E5%B0%BE%E8%91%B5Dypsis_lutescens_20210511145013_05.jpg/500px-%E6%95%A3%E5%B0%BE%E8%91%B5Dypsis_lutescens_20210511145013_05.jpg","license":"CC BY-SA 4.0","attribution":"Ping an Chang","source_url":"https://commons.wikimedia.org/wiki/File:%E6%95%A3%E5%B0%BE%E8%91%B5Dypsis_lutescens_20210511145013_05.jpg"}'::jsonb, '2026-11-02', null),
('strelitzia-reginae', 'Strelitzia reginae', 'Strelitziaceae', 'Bird of Paradise', 'عصفور الجنة', 'Paddle-shaped leaves and, in strong light, striking orange and blue flowers resembling a bird''s head.', 'أوراق على شكل مجداف، وفي الضوء القوي أزهار برتقالية وزرقاء لافتة تشبه رأس طائر.', array['bright_indirect','full_sun']::text[], 'moderate', 'moderate', 12, 38, array['indoor','outdoor']::text[], 'moderate', 'large', 'upright', true, true, false, false, array['Needs lots of light to flower.','Split leaves are natural and help in wind.']::text[], array['تحتاج إضاءة كثيرة عشان تزهر.','تشقق الأوراق طبيعي ويساعدها مع الهواء.']::text[], array['No flowers in insufficient light','Curling leaves when underwatered']::text[], array['عدم التزهير مع قلة الإضاءة','التفاف الأوراق عند قلة الري']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Strelitzia%20reginae','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Strelitzia%20reginae']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'strelitzia reginae', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Strelitzia_reginae_MHNT.BOT.2009.13.52.jpg/960px-Strelitzia_reginae_MHNT.BOT.2009.13.52.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Strelitzia_reginae_MHNT.BOT.2009.13.52.jpg/500px-Strelitzia_reginae_MHNT.BOT.2009.13.52.jpg","license":"CC BY-SA 3.0","attribution":"Roger Culos","source_url":"https://commons.wikimedia.org/wiki/File:Strelitzia_reginae_MHNT.BOT.2009.13.52.jpg"}'::jsonb, '2026-11-02', null),
('hoya-carnosa', 'Hoya carnosa', 'Apocynaceae', 'Wax Plant', 'هويا', 'A trailing vine with waxy leaves and clusters of star-shaped, sweetly scented flowers.', 'متدلية بأوراق شمعية وعناقيد أزهار نجمية الشكل ذات رائحة حلوة.', array['medium','bright_indirect']::text[], 'low', 'moderate', 15, 30, array['indoor']::text[], 'easy', 'small', 'trailing', false, true, false, false, array['Let soil dry between waterings.','Don''t cut old flower spurs; they rebloom.']::text[], array['خل التربة تجف بين الريّات.','لا تقص حوامل الأزهار القديمة لأنها تزهر مرة ثانية.']::text[], array['No flowers in low light','Mealybugs on stems']::text[], array['عدم التزهير في الإضاءة الضعيفة','البق الدقيقي على السيقان']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Hoya%20carnosa','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Hoya%20carnosa']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'hoya carnosa', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/NKN-2007-06-13_114250_Hoya_Carnosa_%28Yvan_Leduc_author_for_Wikipedia%29.jpg/960px-NKN-2007-06-13_114250_Hoya_Carnosa_%28Yvan_Leduc_author_for_Wikipedia%29.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/NKN-2007-06-13_114250_Hoya_Carnosa_%28Yvan_Leduc_author_for_Wikipedia%29.jpg/500px-NKN-2007-06-13_114250_Hoya_Carnosa_%28Yvan_Leduc_author_for_Wikipedia%29.jpg","license":"CC BY-SA 3.0","attribution":"Yvan leduc","source_url":"https://commons.wikimedia.org/wiki/File:NKN-2007-06-13_114250_Hoya_Carnosa_(Yvan_Leduc_author_for_Wikipedia).jpg"}'::jsonb, '2026-11-02', null),
('nephrolepis-exaltata', 'Nephrolepis exaltata', 'Nephrolepidaceae', 'Boston Fern', 'سرخس بوسطن', 'Lush arching fronds for hanging baskets; needs steady moisture and humidity.', 'سعف كثيف مقوس للسلال المعلقة؛ يحتاج رطوبة ثابتة في التربة والهواء.', array['medium','bright_indirect']::text[], 'high', 'high', 15, 28, array['indoor']::text[], 'moderate', 'medium', 'trailing', false, false, false, false, array['Never let the soil dry out completely.','Bathrooms with a window suit it well.']::text[], array['لا تخلي التربة تجف تمامًا.','الحمامات اللي فيها شباك تناسبه جدًا.']::text[], array['Shedding brown leaflets in dry air','Pale fronds in direct sun']::text[], array['تساقط وريقات بنية في الهواء الجاف','شحوب السعف في الشمس المباشرة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Nephrolepis%20exaltata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Nephrolepis%20exaltata']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'nephrolepis exaltata', '2026-11-02', '{"url":"https://upload.wikimedia.org/wikipedia/commons/3/30/Boston_Fern_%282873392811%29.png","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/3/30/Boston_Fern_%282873392811%29.png","license":"CC BY 2.0","attribution":"Homer Edward Price","source_url":"https://commons.wikimedia.org/wiki/File:Boston_Fern_(2873392811).png"}'::jsonb, '2026-11-02', null),
('jasminum-sambac', 'Jasminum sambac', 'Oleaceae', 'Arabian Jasmine', 'فل عربي', 'The beloved full of Arabian homes: an evergreen shrub with intensely fragrant white flowers through the warm months.', 'الفل المحبوب في البيوت العربية: شجيرة دائمة الخضرة بأزهار بيضاء فواحة طوال الأشهر الدافئة.', array['bright_indirect','full_sun']::text[], 'moderate', 'moderate', 10, 40, array['outdoor','indoor']::text[], 'moderate', 'medium', 'bushy', true, true, true, false, array['Needs bright light, ideally morning sun, to flower.','Feed lightly every month in the growing season.']::text[], array['يحتاج إضاءة قوية، ويفضّل شمس الصباح، عشان يزهر.','سمّده خفيف كل شهر في موسم النمو.']::text[], array['Bud drop from irregular watering','Whitefly and mealybugs']::text[], array['تساقط البراعم من الري غير المنتظم','الذبابة البيضاء والبق الدقيقي']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Jasminum%20sambac','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Jasminum%20sambac']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'jasminum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Arabian_jasmin%2C_Tunisia_2010.jpg/960px-Arabian_jasmin%2C_Tunisia_2010.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Arabian_jasmin%2C_Tunisia_2010.jpg/500px-Arabian_jasmin%2C_Tunisia_2010.jpg","license":"CC BY-SA 3.0","attribution":"Habib M''henni","source_url":"https://commons.wikimedia.org/wiki/File:Arabian_jasmin,_Tunisia_2010.jpg"}'::jsonb, '2026-11-02', null),
('lavandula-angustifolia', 'Lavandula angustifolia', 'Lamiaceae', 'English Lavender', 'لافندر (خزامى)', 'Silvery aromatic foliage and purple flower spikes; loves sun and dry, well-drained soil.', 'أوراق فضية عطرية وسنابل زهرية بنفسجية؛ تحب الشمس والتربة الجافة جيدة التصريف.', array['full_sun']::text[], 'low', 'low', 0, 35, array['outdoor']::text[], 'moderate', 'small', 'bushy', false, true, true, false, array['Use gritty soil and a terracotta pot.','Shade from the harshest midsummer afternoon sun.']::text[], array['استخدم تربة حصوية وأصيص فخار.','ظلّلها من شمس العصر القاسية في عز الصيف.']::text[], array['Root rot in wet or humid conditions','Woody, sparse growth without pruning']::text[], array['تعفن الجذور في الرطوبة أو التربة المبللة','نمو خشبي متفرق بدون تقليم']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Lavandula%20angustifolia','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Lavandula%20angustifolia']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://upload.wikimedia.org/wikipedia/commons/4/40/Lavandula_angustifolia_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-087.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/4/40/Lavandula_angustifolia_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-087.jpg","license":"Public domain","attribution":"Franz Eugen Köhler, Köhler''s Medizinal-Pflanzen","source_url":"https://commons.wikimedia.org/wiki/File:Lavandula_angustifolia_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-087.jpg"}'::jsonb, '2026-11-02', null),
('catharanthus-roseus', 'Catharanthus roseus', 'Apocynaceae', 'Madagascar Periwinkle', 'الونكة', 'A heat-loving bedding plant that flowers non-stop in pink, white and red through hot summers.', 'نبتة أحواض تحب الحرارة وتزهر بدون توقف بالوردي والأبيض والأحمر طوال الصيف الحار.', array['full_sun']::text[], 'low', 'low', 12, 42, array['outdoor']::text[], 'easy', 'small', 'bushy', true, true, false, false, array['Thrives in heat; avoid overwatering.','Great for balcony planters with full sun.']::text[], array['تزدهر في الحرارة؛ تجنب زيادة الري.','ممتازة لأحواض البلكونة المشمسة.']::text[], array['Root rot in soggy soil','Leggy plants in shade']::text[], array['تعفن الجذور في التربة المشبعة','نمو طويل ضعيف في الظل']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Catharanthus%20roseus','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Catharanthus%20roseus']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'vinca rosea', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Catharanthus_roseus_flower_bud%2C_Burdwan%2C_West_Bengal%2C_India_12_09_2012.JPG/960px-Catharanthus_roseus_flower_bud%2C_Burdwan%2C_West_Bengal%2C_India_12_09_2012.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Catharanthus_roseus_flower_bud%2C_Burdwan%2C_West_Bengal%2C_India_12_09_2012.JPG/500px-Catharanthus_roseus_flower_bud%2C_Burdwan%2C_West_Bengal%2C_India_12_09_2012.JPG","license":"CC BY-SA 3.0","attribution":"Joydeep","source_url":"https://commons.wikimedia.org/wiki/File:Catharanthus_roseus_flower_bud,_Burdwan,_West_Bengal,_India_12_09_2012.JPG"}'::jsonb, '2026-11-02', null),
('nerium-oleander', 'Nerium oleander', 'Apocynaceae', 'Oleander', 'الدفلة', 'A tough flowering shrub common in Saudi landscapes; extremely drought- and heat-tolerant but highly toxic.', 'شجيرة مزهرة قوية منتشرة في حدائق السعودية؛ تتحمل الجفاف والحرارة جدًا لكنها شديدة السمية.', array['full_sun']::text[], 'low', 'low', 0, 45, array['outdoor']::text[], 'easy', 'large', 'bushy', true, true, false, false, array['All parts are poisonous; wear gloves when pruning.','Keep away from children and pets.']::text[], array['كل أجزائها سامة؛ البس قفازات وقت التقليم.','أبعدها عن الأطفال والحيوانات الأليفة.']::text[], array['Aphids on new shoots','Fewer flowers in shade']::text[], array['المن على الأفرع الجديدة','قلة الأزهار في الظل']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Nerium%20oleander','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Nerium%20oleander']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'nerium oleander', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Nerium_oleander_flowers_leaves.jpg/960px-Nerium_oleander_flowers_leaves.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Nerium_oleander_flowers_leaves.jpg/500px-Nerium_oleander_flowers_leaves.jpg","license":"CC BY 2.5","attribution":"Alvesgaspar","source_url":"https://commons.wikimedia.org/wiki/File:Nerium_oleander_flowers_leaves.jpg"}'::jsonb, '2026-11-02', null),
('phoenix-roebelenii', 'Phoenix roebelenii', 'Arecaceae', 'Pygmy Date Palm', 'نخلة الزينة القزمية', 'A small relative of the date palm with fine, arching fronds; elegant in large pots on terraces.', 'قريبة صغيرة لنخلة التمر بسعف ناعم مقوس؛ أنيقة في الأصص الكبيرة على التراسات.', array['bright_indirect','full_sun']::text[], 'moderate', 'moderate', 5, 40, array['outdoor','indoor']::text[], 'moderate', 'large', 'tree', true, false, false, false, array['Water deeply when the top 5 cm is dry.','Spines at the frond base: handle with care.']::text[], array['اسقها ريّة عميقة لما تجف أول ٥ سم.','فيها أشواك عند قاعدة السعف؛ تعامل معها بحذر.']::text[], array['Yellowing fronds from nutrient deficiency','Scale insects']::text[], array['اصفرار السعف من نقص العناصر','الحشرات القشرية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Phoenix%20roebelenii','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Phoenix%20roebelenii']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'phoenix robellinii', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Starr_070124-3839_Phoenix_roebelenii.jpg/960px-Starr_070124-3839_Phoenix_roebelenii.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Starr_070124-3839_Phoenix_roebelenii.jpg/500px-Starr_070124-3839_Phoenix_roebelenii.jpg","license":"CC BY 3.0","attribution":"Forest &amp; Kim Starr","source_url":"https://commons.wikimedia.org/wiki/File:Starr_070124-3839_Phoenix_roebelenii.jpg"}'::jsonb, '2026-11-02', null),
('ixora-coccinea', 'Ixora coccinea', 'Rubiaceae', 'Jungle Geranium', 'إكسورا', 'Dense clusters of red-orange flowers on a glossy evergreen shrub; prefers slightly acidic soil.', 'عناقيد كثيفة من الأزهار البرتقالية الحمراء على شجيرة دائمة الخضرة لامعة؛ تفضل التربة الحمضية قليلًا.', array['bright_indirect','full_sun']::text[], 'moderate', 'moderate', 13, 38, array['outdoor']::text[], 'moderate', 'medium', 'bushy', true, true, false, false, array['Use an acidic fertiliser to prevent yellow leaves.','Morning sun with light afternoon shade is ideal.']::text[], array['استخدم سماد حمضي عشان تمنع اصفرار الأوراق.','شمس الصباح مع ظل خفيف العصر مثالية.']::text[], array['Chlorosis (yellow leaves, green veins) in alkaline soil','Aphids']::text[], array['اصفرار الأوراق مع بقاء العروق خضراء في التربة القلوية','المن']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Ixora%20coccinea','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Ixora%20coccinea']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'ixora coccinea', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Ixora_coccinea.jpg/960px-Ixora_coccinea.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Ixora_coccinea.jpg/500px-Ixora_coccinea.jpg","license":"CC BY-SA 3.0","attribution":"User:Kokkarani","source_url":"https://commons.wikimedia.org/wiki/File:Ixora_coccinea.jpg"}'::jsonb, '2026-11-02', null),
('portulaca-grandiflora', 'Portulaca grandiflora', 'Portulacaceae', 'Moss Rose', 'بورتولاكا (الرجلة المزهرة)', 'A low succulent annual whose bright flowers open in full sun; thrives in heat and poor soil.', 'نبتة عصارية حولية منخفضة تتفتح أزهارها الزاهية في الشمس الكاملة؛ تزدهر في الحرارة والتربة الفقيرة.', array['full_sun']::text[], 'low', 'low', 15, 45, array['outdoor']::text[], 'easy', 'small', 'trailing', true, true, false, true, array['Flowers close on cloudy days; that''s normal.','Water sparingly; tolerates drought.']::text[], array['الأزهار تقفل في الأيام الغائمة وهذا طبيعي.','اسقها بقلة لأنها تتحمل الجفاف.']::text[], array['Rot in wet soil','Few flowers in shade']::text[], array['التعفن في التربة المبللة','قلة الأزهار في الظل']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Portulaca%20grandiflora','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Portulaca%20grandiflora']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/PortulacaGrandiflora.jpg/960px-PortulacaGrandiflora.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/PortulacaGrandiflora.jpg/500px-PortulacaGrandiflora.jpg","license":"CC BY-SA 4.0","attribution":"Anshik Kumar Tiwari","source_url":"https://commons.wikimedia.org/wiki/File:PortulacaGrandiflora.jpg"}'::jsonb, '2026-11-02', null),
('echinocactus-grusonii', 'Echinocactus grusonii', 'Cactaceae', 'Golden Barrel Cactus', 'صبار البرميل الذهبي', 'A sculptural globe of golden spines; extremely drought tolerant and happy in full sun.', 'كرة نحتية من الأشواك الذهبية؛ تتحمل الجفاف بشكل كبير وترتاح في الشمس الكاملة.', array['full_sun','bright_indirect']::text[], 'low', 'low', 5, 45, array['outdoor','indoor']::text[], 'easy', 'small', 'rosette', true, false, false, true, array['Water monthly in summer, rarely in winter.','Handle with folded newspaper or thick gloves.']::text[], array['اسقه مرة بالشهر في الصيف ونادرًا في الشتاء.','امسكه بورق جرائد مطوي أو قفازات سميكة.']::text[], array['Base rot from overwatering','Sunburn if moved suddenly into full sun']::text[], array['تعفن القاعدة من زيادة الري','حروق الشمس إذا نُقل فجأة للشمس الكاملة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Echinocactus%20grusonii','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Echinocactus%20grusonii']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Echinocactus_grusonii_%28aka%29.jpg/960px-Echinocactus_grusonii_%28aka%29.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Echinocactus_grusonii_%28aka%29.jpg/500px-Echinocactus_grusonii_%28aka%29.jpg","license":"CC BY-SA 2.5","attribution":"André Karwath aka Aka","source_url":"https://commons.wikimedia.org/wiki/File:Echinocactus_grusonii_(aka).jpg"}'::jsonb, '2026-11-02', null),
('curio-rowleyanus', 'Curio rowleyanus', 'Asteraceae', 'String of Pearls', 'عقد اللؤلؤ', 'A trailing succulent with bead-like leaves that cascade beautifully from hanging pots.', 'عصارية متدلية بأوراق تشبه الخرز تنساب بجمال من الأصص المعلقة.', array['bright_indirect']::text[], 'low', 'low', 10, 32, array['indoor']::text[], 'moderate', 'small', 'trailing', false, false, false, true, array['Water when the pearls look slightly wrinkled.','Use a shallow pot with gritty soil.']::text[], array['اسقها لما يبان على اللؤلؤ تجعد خفيف.','استخدم أصيص قليل العمق مع تربة حصوية.']::text[], array['Mushy pearls from overwatering','Bare crown in low light']::text[], array['طراوة اللؤلؤ من زيادة الري','فراغ في قمة النبتة مع الإضاءة الضعيفة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Curio%20rowleyanus','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Curio%20rowleyanus']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'senecio', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Senecio_rowleyanus_leaves.jpg/960px-Senecio_rowleyanus_leaves.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Senecio_rowleyanus_leaves.jpg/500px-Senecio_rowleyanus_leaves.jpg","license":"CC BY 2.0","attribution":"Flickr user Forest and Kim Starr","source_url":"https://commons.wikimedia.org/wiki/File:Senecio_rowleyanus_leaves.jpg"}'::jsonb, '2026-11-02', null),
('tradescantia-zebrina', 'Tradescantia zebrina', 'Commelinaceae', 'Inch Plant', 'تراديسكانتيا زيبرينا', 'Purple and silver striped leaves on fast trailing stems; colours are richest in bright light.', 'أوراق مخططة بالبنفسجي والفضي على سيقان متدلية سريعة؛ ألوانها أقوى في الإضاءة الجيدة.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 13, 30, array['indoor']::text[], 'easy', 'small', 'trailing', false, false, false, false, array['Pinch tips often to keep it compact.','Cuttings root easily in water.']::text[], array['اقرص الأطراف باستمرار عشان تبقى مرتبة.','العُقل تتجذر بسهولة في الماء.']::text[], array['Faded colour in low light','Leggy growth over time']::text[], array['بهتان اللون في الإضاءة الضعيفة','نمو طويل متفرق مع الوقت']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Tradescantia%20zebrina','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Tradescantia%20zebrina']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Zebrina_pendula_20060521_2_closer.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Zebrina_pendula_20060521_2_closer.jpg","license":"CC BY-SA 3.0","attribution":"Ruestz (upload 13:54, 11 January 2008)","source_url":"https://commons.wikimedia.org/wiki/File:Zebrina_pendula_20060521_2_closer.jpg"}'::jsonb, '2026-11-02', null),
('phalaenopsis-hybrid', 'Phalaenopsis hybrids', 'Orchidaceae', 'Moth Orchid', 'أوركيد الفراشة', 'Elegant arching sprays of long-lasting flowers; grown in bark rather than soil.', 'سيقان مقوسة أنيقة بأزهار تدوم طويلًا؛ تُزرع في لحاء الشجر بدل التربة.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 18, 30, array['indoor']::text[], 'moderate', 'small', 'upright', false, true, false, false, array['Water when the roots turn silvery, about weekly.','Never leave water standing in the crown.']::text[], array['اسقها لما تصير الجذور فضية، تقريبًا كل أسبوع.','لا تخلي الماء واقف في قلب النبتة.']::text[], array['Root rot from soggy bark','Bud blast from sudden temperature changes']::text[], array['تعفن الجذور من اللحاء المشبع','تساقط البراعم من تغير الحرارة المفاجئ']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Phalaenopsis','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Phalaenopsis']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'phalaenopsis', '2026-11-02', '{"url":"https://upload.wikimedia.org/wikipedia/commons/1/1e/Phalaenopsis_philippinensis_NationalOrchidGarden-Singapore.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/1/1e/Phalaenopsis_philippinensis_NationalOrchidGarden-Singapore.jpg","license":"CC BY-SA 3.0","attribution":null,"source_url":"https://commons.wikimedia.org/wiki/File:Phalaenopsis_philippinensis_NationalOrchidGarden-Singapore.jpg"}'::jsonb, '2026-11-02', null),
('anthurium-andraeanum', 'Anthurium andraeanum', 'Araceae', 'Flamingo Flower', 'أنثوريوم', 'Glossy heart-shaped red spathes that last for weeks; a popular gift plant.', 'أغلفة زهرية حمراء لامعة على شكل قلب تدوم لأسابيع؛ من نباتات الهدايا المحبوبة.', array['medium','bright_indirect']::text[], 'moderate', 'high', 18, 30, array['indoor']::text[], 'moderate', 'medium', 'upright', false, true, false, false, array['Bright indirect light keeps it flowering.','Let the top 3 cm dry between waterings.']::text[], array['الإضاءة غير المباشرة القوية تخليها تزهر.','خل أول ٣ سم تجف بين الريّات.']::text[], array['Brown leaf tips in dry air','No new flowers in low light']::text[], array['أطراف بنية في الهواء الجاف','عدم ظهور أزهار جديدة في الإضاءة الضعيفة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Anthurium%20andraeanum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Anthurium%20andraeanum']::text[], 'unknown', 'unknown', null, null, null, null, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/AnthuriumAndraenum.jpg/960px-AnthuriumAndraenum.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/AnthuriumAndraenum.jpg/500px-AnthuriumAndraenum.jpg","license":"CC BY 2.5","attribution":"Taken by Fanghong","source_url":"https://commons.wikimedia.org/wiki/File:AnthuriumAndraenum.jpg"}'::jsonb, '2026-11-02', null),
('dracaena-marginata', 'Dracaena marginata', 'Asparagaceae', 'Dragon Tree', 'دراسينا مارجيناتا', 'Slender trunks topped with spiky red-edged leaves; an architectural, low-maintenance indoor tree.', 'جذوع نحيلة تعلوها أوراق شوكية بحواف حمراء؛ شجرة داخلية معمارية قليلة العناية.', array['medium','bright_indirect']::text[], 'low', 'low', 15, 32, array['indoor']::text[], 'easy', 'large', 'tree', false, false, false, false, array['Water when the top half of soil is dry.','Sensitive to fluoride; use filtered water if tips brown.']::text[], array['اسقها لما يجف نصف التربة العلوي.','حساسة للفلورايد؛ استخدم ماء مفلتر إذا اسمرّت الأطراف.']::text[], array['Brown tips from tap water salts','Leaf drop from overwatering']::text[], array['أطراف بنية من أملاح ماء الحنفية','تساقط الأوراق من زيادة الري']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Dracaena%20marginata','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Dracaena%20marginata']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'dracaena marginata', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Dracaena_reflexa.JPG/960px-Dracaena_reflexa.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Dracaena_reflexa.JPG/500px-Dracaena_reflexa.JPG","license":"CC BY-SA 3.0","attribution":"No machine-readable author provided. B.navez assumed (based on copyright claims).","source_url":"https://commons.wikimedia.org/wiki/File:Dracaena_reflexa.JPG"}'::jsonb, '2026-11-02', null),
('pelargonium-graveolens', 'Pelargonium graveolens', 'Geraniaceae', 'Rose Geranium', 'عطرة (جيرانيوم وردي)', 'Soft, deeply cut leaves release a rose-like scent when touched; thrives on sunny balconies.', 'أوراق ناعمة عميقة التقطيع تفوح منها رائحة الورد عند لمسها؛ تزدهر في البلكونات المشمسة.', array['bright_indirect','full_sun']::text[], 'low', 'low', 5, 35, array['outdoor','indoor']::text[], 'easy', 'small', 'bushy', false, true, true, false, array['Let soil dry slightly between waterings.','Pinch tips to keep it compact.']::text[], array['خل التربة تجف قليلًا بين الريّات.','اقرص الأطراف عشان تبقى مرتبة.']::text[], array['Leggy growth in shade','Grey mould in humid, still air']::text[], array['نمو طويل ضعيف في الظل','العفن الرمادي في الهواء الرطب الراكد']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Pelargonium%20graveolens','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Pelargonium%20graveolens']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'pelargonium', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/%28MHNT%29_Pelargonium_graveolens_flower_and_leaves.jpg/960px-%28MHNT%29_Pelargonium_graveolens_flower_and_leaves.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/%28MHNT%29_Pelargonium_graveolens_flower_and_leaves.jpg/500px-%28MHNT%29_Pelargonium_graveolens_flower_and_leaves.jpg","license":"CC BY-SA 4.0","attribution":"Didier Descouens","source_url":"https://commons.wikimedia.org/wiki/File:(MHNT)_Pelargonium_graveolens_flower_and_leaves.jpg"}'::jsonb, '2026-11-02', null),
('hedera-helix', 'Hedera helix', 'Araliaceae', 'English Ivy', 'لبلاب', 'A classic evergreen climber and trailer with lobed leaves; prefers cool, bright conditions.', 'متسلقة ومتدلية دائمة الخضرة كلاسيكية بأوراق مفصصة؛ تفضل الأجواء المضيئة المعتدلة.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 8, 28, array['indoor','outdoor']::text[], 'moderate', 'medium', 'climbing', false, false, false, false, array['Prefers cooler rooms; struggles in hot, dry air.','Shower leaves occasionally to deter spider mites.']::text[], array['تفضل الغرف المعتدلة وتتعب في الهواء الحار الجاف.','رش الأوراق بالماء أحيانًا عشان تبعد العنكبوت الأحمر.']::text[], array['Spider mites in warm, dry rooms','Crispy leaves from heat']::text[], array['العنكبوت الأحمر في الغرف الحارة الجافة','جفاف الأوراق من الحرارة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Hedera%20helix','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Hedera%20helix']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'hedera helix', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Ivy_Hedera_Red_Brick_Wall_2892px.jpg/960px-Ivy_Hedera_Red_Brick_Wall_2892px.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Ivy_Hedera_Red_Brick_Wall_2892px.jpg/500px-Ivy_Hedera_Red_Brick_Wall_2892px.jpg","license":"GFDL 1.2","attribution":"Photo by and (c)2007 Derek Ramsey (Ram-Man)","source_url":"https://commons.wikimedia.org/wiki/File:Ivy_Hedera_Red_Brick_Wall_2892px.jpg"}'::jsonb, '2026-11-02', null),
('kalanchoe-blossfeldiana', 'Kalanchoe blossfeldiana', 'Crassulaceae', 'Flaming Katy', 'كالانشو', 'A compact succulent covered in clusters of bright flowers for weeks; a cheerful, easy gift.', 'عصارية صغيرة تغطيها عناقيد أزهار زاهية لأسابيع؛ هدية مبهجة وسهلة.', array['bright_indirect','full_sun']::text[], 'low', 'low', 10, 32, array['indoor','outdoor']::text[], 'easy', 'small', 'bushy', false, true, false, true, array['Water when soil is dry to the touch.','Remove spent flower heads to tidy the plant.']::text[], array['اسقها لما تكون التربة جافة باللمس.','شيل الأزهار الذابلة عشان ترتب النبتة.']::text[], array['Rot from overwatering','Stretching in low light']::text[], array['التعفن من زيادة الري','الاستطالة في الإضاءة الضعيفة']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Kalanchoe%20blossfeldiana','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Kalanchoe%20blossfeldiana']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'kalanchoe', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/2025_Kalanchoe_blossfeldiana_Poelin._Santiago_de_Compostela._Galiza-2.jpg/960px-2025_Kalanchoe_blossfeldiana_Poelin._Santiago_de_Compostela._Galiza-2.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/2025_Kalanchoe_blossfeldiana_Poelin._Santiago_de_Compostela._Galiza-2.jpg/500px-2025_Kalanchoe_blossfeldiana_Poelin._Santiago_de_Compostela._Galiza-2.jpg","license":"CC BY-SA 4.0","attribution":"Luis Miguel Bugallo Sánchez","source_url":"https://commons.wikimedia.org/wiki/File:2025_Kalanchoe_blossfeldiana_Poelin._Santiago_de_Compostela._Galiza-2.jpg"}'::jsonb, '2026-11-02', null),
('gardenia-jasminoides', 'Gardenia jasminoides', 'Rubiaceae', 'Gardenia', 'جاردينيا', 'Glossy evergreen leaves and creamy, intensely perfumed flowers; rewarding but needs consistent care.', 'أوراق لامعة دائمة الخضرة وأزهار كريمية فواحة؛ مجزية لكنها تحتاج عناية منتظمة.', array['bright_indirect']::text[], 'moderate', 'high', 15, 30, array['indoor','outdoor']::text[], 'hard', 'medium', 'bushy', false, true, true, false, array['Use acidic potting mix and rainwater or filtered water.','Avoid moving it while in bud.']::text[], array['استخدم تربة حمضية وماء مفلتر.','لا تحركها وهي مبرعمة.']::text[], array['Bud drop from dry air or moving','Yellow leaves in alkaline soil']::text[], array['تساقط البراعم من الهواء الجاف أو التحريك','اصفرار الأوراق في التربة القلوية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Gardenia%20jasminoides','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Gardenia%20jasminoides']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'gardenia jasminoides', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Gardenia_jasminoides_1DS-II_2-5672.jpg/960px-Gardenia_jasminoides_1DS-II_2-5672.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Gardenia_jasminoides_1DS-II_2-5672.jpg/500px-Gardenia_jasminoides_1DS-II_2-5672.jpg","license":"CC BY-SA 4.0","attribution":"SAplants","source_url":"https://commons.wikimedia.org/wiki/File:Gardenia_jasminoides_1DS-II_2-5672.jpg"}'::jsonb, '2026-11-02', null),
('adenium-obesum', 'Adenium obesum', 'Apocynaceae', 'Desert Rose', 'وردة الصحراء', 'A swollen-trunked succulent native to the Arabian Peninsula and Africa, with trumpet-shaped pink flowers in heat.', 'عصارية بجذع منتفخ، موطنها شبه الجزيرة العربية وأفريقيا، تحمل أزهارًا وردية بوقية الشكل في الحر.', array['full_sun']::text[], 'low', 'low', 10, 45, array['outdoor','indoor']::text[], 'moderate', 'medium', 'tree', true, true, false, true, array['Give maximum sun; it loves Saudi summers.','Keep dry in cool months; sap is toxic.']::text[], array['أعطها أكبر قدر من الشمس؛ تحب صيف السعودية.','خلها جافة في الأشهر الباردة؛ عصارتها سامة.']::text[], array['Caudex rot from cold, wet soil','Leaf drop in winter (normal dormancy)']::text[], array['تعفن الجذع من التربة الباردة المبللة','تساقط الأوراق في الشتاء (سكون طبيعي)']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Adenium%20obesum','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Adenium%20obesum']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'adenium obesum', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Double_Petal_Flower_Side_Front_Adenium_Obesum_Graft_Apr22_D72_23135-151_ZS_Pr.jpg/960px-Double_Petal_Flower_Side_Front_Adenium_Obesum_Graft_Apr22_D72_23135-151_ZS_Pr.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Double_Petal_Flower_Side_Front_Adenium_Obesum_Graft_Apr22_D72_23135-151_ZS_Pr.jpg/500px-Double_Petal_Flower_Side_Front_Adenium_Obesum_Graft_Apr22_D72_23135-151_ZS_Pr.jpg","license":"CC BY-SA 4.0","attribution":"This Photo was taken by Timothy A. Gonsalves. Feel free to use my photos, but please mention me as the author. I would much appreciate if you send me an email tagooty@yahoo.com or write on my talk page, for my information. Please contact me before commercial use. Please do not upload an edited image here without consulting me. I would like to make corrections only at my own source to ensure that the changes improve the image and are preserved.Otherwise you may upload an edited image with a new name. Please use one of the templates derivative or extract.","source_url":"https://commons.wikimedia.org/wiki/File:Double_Petal_Flower_Side_Front_Adenium_Obesum_Graft_Apr22_D72_23135-151_ZS_Pr.jpg"}'::jsonb, '2026-11-02', null),
('ficus-benjamina', 'Ficus benjamina', 'Moraceae', 'Weeping Fig', 'فيكس بنجامينا', 'A graceful indoor tree with small glossy leaves on arching branches.', 'شجرة داخلية رشيقة بأوراق صغيرة لامعة على أغصان مقوسة.', array['bright_indirect']::text[], 'moderate', 'moderate', 15, 30, array['indoor','outdoor']::text[], 'moderate', 'large', 'tree', false, false, false, false, array['Choose a bright spot and keep it there.','Water when the top 3 cm of soil is dry.']::text[], array['اختر لها مكان مضيء وخلها فيه.','اسقها لما تجف أول ٣ سم من التربة.']::text[], array['Sudden leaf drop after moving','Scale insects']::text[], array['تساقط مفاجئ للأوراق بعد النقل','الحشرات القشرية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Ficus%20benjamina','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Ficus%20benjamina']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'ficus benjamina', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Ficus_benjamina-weeping_fig-benjamin_fig_01.jpg/960px-Ficus_benjamina-weeping_fig-benjamin_fig_01.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Ficus_benjamina-weeping_fig-benjamin_fig_01.jpg/500px-Ficus_benjamina-weeping_fig-benjamin_fig_01.jpg","license":"CC BY-SA 4.0","attribution":"Vijayanrajapuram","source_url":"https://commons.wikimedia.org/wiki/File:Ficus_benjamina-weeping_fig-benjamin_fig_01.jpg"}'::jsonb, '2026-11-02', null),
('schefflera-arboricola', 'Schefflera arboricola', 'Araliaceae', 'Dwarf Umbrella Tree', 'شيفليرا', 'Glossy leaflets arranged like umbrella spokes; a sturdy, adaptable plant for homes and offices.', 'وريقات لامعة مرتبة مثل أضلاع المظلة؛ نبتة قوية متأقلمة للبيوت والمكاتب.', array['medium','bright_indirect']::text[], 'moderate', 'moderate', 13, 32, array['indoor','outdoor']::text[], 'easy', 'medium', 'bushy', false, false, false, false, array['Water when the top 3–5 cm is dry.','Prune to shape; it branches readily.']::text[], array['اسقها لما تجف أول ٣–٥ سم.','قصّها عشان تشكلها لأنها تتفرع بسهولة.']::text[], array['Leggy growth in low light','Spider mites and scale']::text[], array['نمو طويل ضعيف في الإضاءة الضعيفة','العنكبوت الأحمر والحشرات القشرية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Schefflera%20arboricola','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Schefflera%20arboricola']::text[], 'toxic', 'toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'schefflera', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Starr-100601-6563-Schefflera_arboricola-small_plant_on_fence_post-Kokomo-Maui_%2824408596974%29.jpg/960px-Starr-100601-6563-Schefflera_arboricola-small_plant_on_fence_post-Kokomo-Maui_%2824408596974%29.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Starr-100601-6563-Schefflera_arboricola-small_plant_on_fence_post-Kokomo-Maui_%2824408596974%29.jpg/500px-Starr-100601-6563-Schefflera_arboricola-small_plant_on_fence_post-Kokomo-Maui_%2824408596974%29.jpg","license":"CC BY 3.0 us","attribution":"Forest and Kim Starr","source_url":"https://commons.wikimedia.org/wiki/File:Starr-100601-6563-Schefflera_arboricola-small_plant_on_fence_post-Kokomo-Maui_(24408596974).jpg"}'::jsonb, '2026-11-02', null),
('calathea-makoyana', 'Goeppertia makoyana', 'Marantaceae', 'Peacock Plant', 'كالاثيا الطاووس', 'Feather-patterned leaves with purple undersides; thrives in warm, humid, shaded rooms.', 'أوراق بنقوش تشبه الريش وظهر بنفسجي؛ تزدهر في الغرف الدافئة الرطبة المظللة.', array['low','medium']::text[], 'high', 'high', 18, 28, array['indoor']::text[], 'hard', 'medium', 'bushy', false, false, false, false, array['Keep soil evenly moist with soft water.','Run a humidifier in AC-cooled rooms.']::text[], array['خل التربة رطبة باستمرار بماء خفيف.','شغّل جهاز ترطيب في الغرف المكيفة.']::text[], array['Curled, crispy leaves in dry air','Brown edges from tap water']::text[], array['التفاف وجفاف الأوراق في الهواء الجاف','حواف بنية من ماء الحنفية']::text[], null, array['https://www.rhs.org.uk/plants/search-results?query=Goeppertia%20makoyana','https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderSearchResults.aspx?basic=Goeppertia%20makoyana']::text[], 'non_toxic', 'non_toxic', 'ASPCA Toxic and Non-Toxic Plant List', 'https://www.aspca.org/pet-care/animal-poison-control/toxic-and-non-toxic-plants', 'calathea', '2026-11-02', '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/CalatheaMakoyana.jpg/960px-CalatheaMakoyana.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/CalatheaMakoyana.jpg/500px-CalatheaMakoyana.jpg","license":"Public domain","attribution":"Chhe (talk)","source_url":"https://commons.wikimedia.org/wiki/File:CalatheaMakoyana.jpg"}'::jsonb, '2026-11-02', null)
