('ee43e0b7-64cb-5f98-8e15-3c521cea7016', 'PL-MON-DEL-M', 'monstera-deliciosa', 'plant', (select id from public.plant_species where slug = 'monstera-deliciosa'), 'Monstera', 'مونستيرا', 'A tropical climbing aroid famous for large, glossy leaves that develop natural splits and holes as they mature.', 'نبتة استوائية متسلقة تشتهر بأوراقها الكبيرة اللامعة التي تظهر فيها شقوق وفتحات طبيعية كلما نضجت.', '21 cm nursery pot', 'أصيص تربية 21 سم', 189, null, 24, true, true, true, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Monstera_deliciosa2.jpg/960px-Monstera_deliciosa2.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Monstera_deliciosa2.jpg/500px-Monstera_deliciosa2.jpg","license":"CC BY-SA 3.0","attribution":null,"source_url":"https://commons.wikimedia.org/wiki/File:Monstera_deliciosa2.jpg"}'::jsonb),
('447e529f-af8c-5d9e-b2fc-be45652b19f2', 'PL-MON-DEL-XL', 'monstera-deliciosa-xl', 'plant', (select id from public.plant_species where slug = 'monstera-deliciosa'), 'Monstera', 'مونستيرا', 'A tropical climbing aroid famous for large, glossy leaves that develop natural splits and holes as they mature.', 'نبتة استوائية متسلقة تشتهر بأوراقها الكبيرة اللامعة التي تظهر فيها شقوق وفتحات طبيعية كلما نضجت.', 'XL with moss pole, 120 cm', 'حجم كبير مع عمود طحلب، ١٢٠ سم', 449, null, 6, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Monstera_deliciosa2.jpg/960px-Monstera_deliciosa2.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Monstera_deliciosa2.jpg/500px-Monstera_deliciosa2.jpg","license":"CC BY-SA 3.0","attribution":null,"source_url":"https://commons.wikimedia.org/wiki/File:Monstera_deliciosa2.jpg"}'::jsonb),
('80b8ba56-da6e-5010-999c-2e1ce971dc63', 'PL-MON-ADA-S', 'monstera-adansonii', 'plant', (select id from public.plant_species where slug = 'monstera-adansonii'), 'Swiss Cheese Vine', 'مونستيرا أدانسوني', 'A vining Monstera with thin leaves full of oval windows, ideal for trailing from shelves or climbing a support.', 'مونستيرا متسلقة بأوراق رقيقة مليئة بفتحات بيضاوية، تناسب الرفوف أو التسلق على دعامة.', '15 cm nursery pot', 'أصيص تربية 15 سم', 79, null, 18, true, false, false, true, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Monstera_adansonii_79319231.jpg/960px-Monstera_adansonii_79319231.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Monstera_adansonii_79319231.jpg/500px-Monstera_adansonii_79319231.jpg","license":"CC BY 4.0","attribution":"Aitor","source_url":"https://commons.wikimedia.org/wiki/File:Monstera_adansonii_79319231.jpg"}'::jsonb),
('4809522d-9bf0-5366-8559-fb9ead5d7583', 'PL-EPI-AUR-S', 'epipremnum-aureum', 'plant', (select id from public.plant_species where slug = 'epipremnum-aureum'), 'Golden Pothos', 'بوتس ذهبي', 'A forgiving trailing vine with heart-shaped, gold-marbled leaves that tolerates a wide range of indoor conditions.', 'نبتة متدلية متسامحة بأوراق قلبية مرقطة بالذهبي، تتحمل ظروفًا داخلية متنوعة.', '14 cm nursery pot', 'أصيص تربية 14 سم', 49, null, 40, true, false, true, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Money_Plant_%28Epipremnum_aureum%29_4.jpg/960px-Money_Plant_%28Epipremnum_aureum%29_4.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Money_Plant_%28Epipremnum_aureum%29_4.jpg/500px-Money_Plant_%28Epipremnum_aureum%29_4.jpg","license":"CC BY-SA 3.0","attribution":"Mokkie","source_url":"https://commons.wikimedia.org/wiki/File:Money_Plant_(Epipremnum_aureum)_4.jpg"}'::jsonb),
('b58e0300-fe63-521c-957c-e539638fd693', 'PL-DRA-TRI-M', 'dracaena-trifasciata', 'plant', (select id from public.plant_species where slug = 'dracaena-trifasciata'), 'Snake Plant', 'نبتة الثعبان (سانسفيريا)', 'Upright, sword-like leaves that store water, making it one of the most drought- and neglect-tolerant houseplants.', 'أوراق قائمة تشبه السيوف وتخزن الماء، من أكثر النباتات الداخلية تحملًا للعطش والإهمال.', '17 cm nursery pot', 'أصيص تربية 17 سم', 95, null, 35, true, true, true, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Dracaena_trifasciata_50695143.jpg/960px-Dracaena_trifasciata_50695143.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Dracaena_trifasciata_50695143.jpg/500px-Dracaena_trifasciata_50695143.jpg","license":"CC BY 4.0","attribution":"Ian Webb","source_url":"https://commons.wikimedia.org/wiki/File:Dracaena_trifasciata_50695143.jpg"}'::jsonb),
('c2cd742d-1db4-56dc-967a-bf1b7991bd19', 'PL-DRA-TRI-L', 'dracaena-trifasciata-tall', 'plant', (select id from public.plant_species where slug = 'dracaena-trifasciata'), 'Snake Plant', 'نبتة الثعبان (سانسفيريا)', 'Upright, sword-like leaves that store water, making it one of the most drought- and neglect-tolerant houseplants.', 'أوراق قائمة تشبه السيوف وتخزن الماء، من أكثر النباتات الداخلية تحملًا للعطش والإهمال.', 'Tall, 90 cm', 'طويلة، ٩٠ سم', 219, null, 10, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Dracaena_trifasciata_50695143.jpg/960px-Dracaena_trifasciata_50695143.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Dracaena_trifasciata_50695143.jpg/500px-Dracaena_trifasciata_50695143.jpg","license":"CC BY 4.0","attribution":"Ian Webb","source_url":"https://commons.wikimedia.org/wiki/File:Dracaena_trifasciata_50695143.jpg"}'::jsonb),
('555de65e-5feb-53db-8162-6feedb49f83c', 'PL-ZAM-ZAM-M', 'zamioculcas-zamiifolia', 'plant', (select id from public.plant_species where slug = 'zamioculcas-zamiifolia'), 'ZZ Plant', 'زاميا (زد زد)', 'Glossy, waxy leaflets grow from underground rhizomes that store water, letting it cope with low light and missed waterings.', 'وريقات لامعة شمعية تنمو من جذامير تحت التربة تخزن الماء، فتتحمل الإضاءة الضعيفة ونسيان الري.', '19 cm nursery pot', 'أصيص تربية 19 سم', 119, null, 28, true, false, true, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Zamioculcas_zamiifolia_1.jpg/960px-Zamioculcas_zamiifolia_1.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Zamioculcas_zamiifolia_1.jpg/500px-Zamioculcas_zamiifolia_1.jpg","license":"CC BY-SA 3.0","attribution":"User:WeFt","source_url":"https://commons.wikimedia.org/wiki/File:Zamioculcas_zamiifolia_1.jpg"}'::jsonb),
('e29516d7-d0b8-59fb-baa7-a7ca3be26459', 'PL-CHL-COM-S', 'chlorophytum-comosum', 'plant', (select id from public.plant_species where slug = 'chlorophytum-comosum'), 'Spider Plant', 'نبتة العنكبوت', 'Arching striped leaves and dangling baby plantlets make it a cheerful, easy plant for shelves and hanging baskets.', 'أوراق مقوسة مخططة ونبتات صغيرة متدلية تجعلها نبتة مبهجة وسهلة للرفوف والسلال المعلقة.', '14 cm nursery pot', 'أصيص تربية 14 سم', 45, null, 30, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Chlorophytum_comosum_in_China.jpg/960px-Chlorophytum_comosum_in_China.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Chlorophytum_comosum_in_China.jpg/500px-Chlorophytum_comosum_in_China.jpg","license":"CC BY-SA 4.0","attribution":"Dinkun Chen","source_url":"https://commons.wikimedia.org/wiki/File:Chlorophytum_comosum_in_China.jpg"}'::jsonb),
('aee9d56e-c507-5056-b489-7c3cd88ef1fe', 'PL-SPA-WAL-M', 'spathiphyllum-wallisii', 'plant', (select id from public.plant_species where slug = 'spathiphyllum-wallisii'), 'Peace Lily', 'زنبق السلام', 'Dark green leaves and elegant white spathes; it droops visibly when thirsty and recovers quickly after watering.', 'أوراق خضراء داكنة وأغلفة زهرية بيضاء أنيقة، تذبل بوضوح لما تعطش وتنتعش بسرعة بعد الري.', '17 cm nursery pot', 'أصيص تربية 17 سم', 89, null, 22, true, true, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Peace_lily_-_1_-_cropped.jpg/960px-Peace_lily_-_1_-_cropped.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Peace_lily_-_1_-_cropped.jpg/500px-Peace_lily_-_1_-_cropped.jpg","license":"CC BY-SA 4.0","attribution":"W.carter","source_url":"https://commons.wikimedia.org/wiki/File:Peace_lily_-_1_-_cropped.jpg"}'::jsonb),
('69d151ba-d672-5f9b-9e92-18eb9811218a', 'PL-FIC-ELA-M', 'ficus-elastica', 'plant', (select id from public.plant_species where slug = 'ficus-elastica'), 'Rubber Plant', 'فيكس مطاطي', 'Thick, glossy, deep-green leaves on an upright trunk; grows into a statement tree with bright light.', 'أوراق سميكة لامعة خضراء داكنة على جذع قائم، تكبر لتصير شجرة لافتة في الإضاءة الجيدة.', '21 cm nursery pot', 'أصيص تربية 21 سم', 149, null, 16, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Ficus_elastica_leaves_02.JPG/960px-Ficus_elastica_leaves_02.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Ficus_elastica_leaves_02.JPG/500px-Ficus_elastica_leaves_02.JPG","license":"CC BY-SA 3.0","attribution":"B.navez","source_url":"https://commons.wikimedia.org/wiki/File:Ficus_elastica_leaves_02.JPG"}'::jsonb),
('6cef7f77-f99d-5712-b4d6-7b0b64899828', 'PL-FIC-LYR-L', 'ficus-lyrata', 'plant', (select id from public.plant_species where slug = 'ficus-lyrata'), 'Fiddle-Leaf Fig', 'فيكس ليراتا', 'Large violin-shaped leaves on a tree form; dramatic but particular about consistent light and watering.', 'أوراق كبيرة على شكل كمان على هيئة شجرة؛ مبهرة لكنها حساسة وتحتاج ثبات في الإضاءة والري.', 'Tree form, 110 cm', 'على شكل شجرة، ١١٠ سم', 349, null, 8, true, true, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Starr_031108-0130_Ficus_lyrata.jpg/960px-Starr_031108-0130_Ficus_lyrata.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Starr_031108-0130_Ficus_lyrata.jpg/500px-Starr_031108-0130_Ficus_lyrata.jpg","license":"CC BY 3.0","attribution":"Forest &amp; Kim Starr","source_url":"https://commons.wikimedia.org/wiki/File:Starr_031108-0130_Ficus_lyrata.jpg"}'::jsonb),
('f31aaa8c-674b-5c2a-bd03-d7f00c244ce9', 'PL-CHA-ELE-M', 'chamaedorea-elegans', 'plant', (select id from public.plant_species where slug = 'chamaedorea-elegans'), 'Parlour Palm', 'نخلة الصالون', 'A compact, slow-growing palm with soft feathery fronds that copes well with indoor shade.', 'نخلة صغيرة بطيئة النمو بسعف ريشي ناعم، تتأقلم جيدًا مع الظل داخل البيت.', '17 cm nursery pot', 'أصيص تربية 17 سم', 99, null, 20, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Chamaedorea_elegans_Mart.JPG/960px-Chamaedorea_elegans_Mart.JPG","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Chamaedorea_elegans_Mart.JPG/500px-Chamaedorea_elegans_Mart.JPG","license":"CC BY-SA 3.0","attribution":"Bachelot Pierre J-P","source_url":"https://commons.wikimedia.org/wiki/File:Chamaedorea_elegans_Mart.JPG"}'::jsonb),
('0bb6621b-a702-5092-b496-c761540f6387', 'PL-PEP-OBT-S', 'peperomia-obtusifolia', 'plant', (select id from public.plant_species where slug = 'peperomia-obtusifolia'), 'Baby Rubber Plant', 'بيبروميا', 'Thick, rounded, semi-succulent leaves on a compact plant that is happy on desks and shelves.', 'أوراق دائرية سميكة شبه عصارية على نبتة صغيرة ترتاح على المكاتب والرفوف.', '12 cm nursery pot', 'أصيص تربية 12 سم', 55, null, 25, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Peperomia_obtusifolia_3-OB9.jpg/960px-Peperomia_obtusifolia_3-OB9.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Peperomia_obtusifolia_3-OB9.jpg/500px-Peperomia_obtusifolia_3-OB9.jpg","license":"CC BY-SA 4.0","attribution":"Jerzy Opioła","source_url":"https://commons.wikimedia.org/wiki/File:Peperomia_obtusifolia_3-OB9.jpg"}'::jsonb),
('027f0aea-a5a6-5f79-b713-8e745aca35cd', 'PL-PIL-PEP-S', 'pilea-peperomioides', 'plant', (select id from public.plant_species where slug = 'pilea-peperomioides'), 'Chinese Money Plant', 'بيليا (نبتة النقود الصينية)', 'Round, coin-like leaves on long stalks; produces offsets that are easy to share.', 'أوراق دائرية تشبه العملات على أعناق طويلة، وتنتج فسائل سهلة المشاركة.', '12 cm nursery pot', 'أصيص تربية 12 سم', 59, null, 18, true, false, false, true, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Pilea_peperomioides_Chinese_money_plant.jpg/960px-Pilea_peperomioides_Chinese_money_plant.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Pilea_peperomioides_Chinese_money_plant.jpg/500px-Pilea_peperomioides_Chinese_money_plant.jpg","license":"CC0","attribution":"Husky","source_url":"https://commons.wikimedia.org/wiki/File:Pilea_peperomioides_Chinese_money_plant.jpg"}'::jsonb),
('af1d2718-bd3c-5a5c-a33e-e031ea0ee8be', 'PL-MAR-LEU-S', 'maranta-leuconeura', 'plant', (select id from public.plant_species where slug = 'maranta-leuconeura'), 'Prayer Plant', 'نبتة الصلاة (مارانتا)', 'Patterned leaves that fold upward at night, which is how it earned the name prayer plant.', 'أوراق منقوشة تنطوي للأعلى في الليل، ومن هنا جاء اسمها نبتة الصلاة.', '14 cm nursery pot', 'أصيص تربية 14 سم', 65, null, 14, true, false, false, false, '{"url":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Maranta_leuconeura3.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Maranta_leuconeura3.jpg","license":"CC BY-SA 3.0","attribution":"Kurt Stüber [1]","source_url":"https://commons.wikimedia.org/wiki/File:Maranta_leuconeura3.jpg"}'::jsonb),
('db66bc96-2b1a-53fc-b0cf-91e68349d00a', 'PL-GOE-ORB-M', 'goeppertia-orbifolia', 'plant', (select id from public.plant_species where slug = 'goeppertia-orbifolia'), 'Calathea Orbifolia', 'كالاثيا أوربيفوليا', 'Broad round leaves with silver-green stripes; a showpiece for humid, shaded rooms.', 'أوراق دائرية عريضة بخطوط فضية خضراء، قطعة مميزة للغرف الرطبة المظللة.', '17 cm nursery pot', 'أصيص تربية 17 سم', 135, null, 9, true, false, false, true, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Houseplant_Calathea_orbifolia.jpg/960px-Houseplant_Calathea_orbifolia.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Houseplant_Calathea_orbifolia.jpg/500px-Houseplant_Calathea_orbifolia.jpg","license":"CC BY-SA 4.0","attribution":"Supsoph","source_url":"https://commons.wikimedia.org/wiki/File:Houseplant_Calathea_orbifolia.jpg"}'::jsonb),
('ea534175-e437-5947-bff9-8ce47ef100f3', 'PL-ALO-VER-S', 'aloe-vera', 'plant', (select id from public.plant_species where slug = 'aloe-vera'), 'Aloe Vera', 'صبار الألوفيرا', 'A sun-loving succulent with thick, gel-filled leaves; very tolerant of heat and dry air.', 'عصارية تحب الشمس بأوراق سميكة مليئة بالجل، تتحمل الحرارة والهواء الجاف بشكل كبير.', '12 cm nursery pot', 'أصيص تربية 12 سم', 39, null, 45, true, false, true, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Aloe_vera_flower_inset.png/960px-Aloe_vera_flower_inset.png","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Aloe_vera_flower_inset.png/500px-Aloe_vera_flower_inset.png","license":"CC BY-SA 3.0","attribution":"Collage by en:User:MidgleyDJ, original images from Wikimedia commons (Image:Aloe_vera_offsets.jpg and Image:Aloe_vera_C.jpg)","source_url":"https://commons.wikimedia.org/wiki/File:Aloe_vera_flower_inset.png"}'::jsonb),
('e0da232a-b775-55ad-b036-855896817a91', 'PL-HAW-ATT-S', 'haworthiopsis-attenuata', 'plant', (select id from public.plant_species where slug = 'haworthiopsis-attenuata'), 'Zebra Haworthia', 'هاورثيا الزيبرا', 'A small rosette succulent with white-striped leaves; tolerates less light than most succulents.', 'عصارية صغيرة على شكل وردة بأوراق مخططة بالأبيض، تتحمل إضاءة أقل من أغلب العصاريات.', '9 cm nursery pot', 'أصيص تربية 9 سم', 35, null, 30, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg/960px-Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg/500px-Winterbourne_-_Haworthia_attenuata_%286120983526%29.jpg","license":"CC BY 2.0","attribution":"stephen boisvert from Chicago, United States","source_url":"https://commons.wikimedia.org/wiki/File:Winterbourne_-_Haworthia_attenuata_(6120983526).jpg"}'::jsonb),
('3924d150-23eb-51de-8579-5d68caa9104c', 'PL-ECH-ELE-S', 'echeveria-elegans', 'plant', (select id from public.plant_species where slug = 'echeveria-elegans'), 'Mexican Snowball', 'إيشيفيريا', 'A pale blue-green rosette succulent that stays compact and colourful in bright light.', 'عصارية وردية بلون أزرق مخضر فاتح، تبقى صغيرة وملونة في الإضاءة القوية.', '9 cm nursery pot', 'أصيص تربية 9 سم', 32, null, 36, true, false, false, false, '{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Echeveria_elegans_-_1.png/960px-Echeveria_elegans_-_1.png","thumb_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Echeveria_elegans_-_1.png/500px-Echeveria_elegans_-_1.png","license":"CC BY-SA 4.0","attribution":"EriaWei","source_url":"https://commons.wikimedia.org/wiki/File:Echeveria_elegans_-_1.png"}'::jsonb),
('64fb3b86-44fe-5a5b-a6c3-81ee41b0ef76', 'PL-CRA-OVA-M', 'crassula-ovata', 'plant', (select id from public.plant_species where slug = 'crassula-ovata'), 'Jade Plant', 'نبتة اليشم (كراسولا)', 'A long-lived succulent shrub with thick oval leaves and woody stems that can be shaped like a bonsai.', 'شجيرة عصارية معمّرة بأوراق بيضاوية سميكة وسيقان خشبية يمكن تشكيلها مثل البونساي.', '17 cm nursery pot', 'أصيص تربية 17 سم', 85, null, 15, true, false, false, false, '{"url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Crassula_ovata_700.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Crassula_ovata_700.jpg","license":"CC BY-SA 3.0","attribution":"author is sannse.","source_url":"https://commons.wikimedia.org/wiki/File:Crassula_ovata_700.jpg"}'::jsonb),
('f09f9cc1-0366-58bb-8cfd-195b4c7a05df', 'PL-BEA-REC-M', 'beaucarnea-recurvata', 'plant', (select id from public.plant_species where slug = 'beaucarnea-recurvata'), 'Ponytail Palm', 'نخلة ذيل الحصان', 'Not a true palm: a swollen trunk stores water beneath a fountain of long, curly leaves. Very heat tolerant.', 'ليست نخلة حقيقية: جذع منتفخ يخزن الماء تحت نافورة من الأوراق الطويلة المتموجة. تتحمل الحرارة بشكل كبير.', '19 cm nursery pot', 'أصيص تربية 19 سم', 165, null, 12, true, true, false, false, '{"url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Beaucarnea_recurvata%2C_Ocampo%2C_Tamaulipas%2C_Mexico_1.jpg","thumb_url":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Beaucarnea_recurvata%2C_Ocampo%2C_Tamaulipas%2C_Mexico_1.jpg","license":"CC BY-SA 4.0","attribution":"juancruzado","source_url":"https://commons.wikimedia.org/wiki/File:Beaucarnea_recurvata,_Ocampo,_Tamaulipas,_Mexico_1.jpg"}'::jsonb),
